// Daily standup digest — runs at 7am Central via cron (or on-demand
// via /webhook/digest-fire). Reads last 24h of family voices from:
//   - /data/finance-events/family-feedback/  (Suggest button submissions)
//   - /data/chatin/                          (@nas / @cpoe / @christiana)
// Summarizes via Ollama 14b. Posts to Synology Chat #PoeTech-PWA channel
// + ntfy family channel.
//
// Per BUSINESS-PROCESS-CONNECTIONS Family-Voice-Is-The-Connection: every
// voice gets acknowledged within 24 hours. This is the morning side of
// that promise.
//
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: summarization is Ollama-14b's
// job (sovereign, free, fast enough). Claude only escalates when a voice
// requires substantive code work.
//
// Per TLC firewall: voices captured here are family voices, classified
// as family-private. Even though Ollama runs on NAS, the OUTPUT still
// goes to Synology Chat + ntfy which are also on NAS. Bright-line
// preserved.

const fs = require('fs');
const path = require('path');

const FEEDBACK_DIR = '/data/finance-events/family-feedback';
const CHATIN_DIR = '/data/chatin';
const OLLAMA_BASE = process.env.OLLAMA_BASE_URL || 'http://ollama:11434';
const OLLAMA_MODEL = process.env.OLLAMA_DIGEST_MODEL || 'qwen2.5:14b-instruct-q4_K_M';
const NTFY_BASE = process.env.NTFY_BASE || 'http://ntfy:80';
const NTFY_TOPIC = process.env.NTFY_FAMILY_FEEDBACK_TOPIC || 'poetech-family-feedback';

const since = Date.now() - 24 * 60 * 60 * 1000;

function safeReadDir(dir) {
  try { return fs.readdirSync(dir); } catch (_) { return []; }
}
function safeReadJson(p) {
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; }
}

// Collect feedback (Suggest button submissions).
const feedbackFiles = safeReadDir(FEEDBACK_DIR);
const feedback = [];
for (const fn of feedbackFiles) {
  if (!fn.endsWith('.json')) continue;
  const rec = safeReadJson(path.join(FEEDBACK_DIR, fn));
  if (!rec || !rec.captured_at) continue;
  if (new Date(rec.captured_at).getTime() < since) continue;
  feedback.push(rec);
}
feedback.sort((a, b) => a.captured_at.localeCompare(b.captured_at));

// Collect @nas chat messages.
const chatFiles = safeReadDir(CHATIN_DIR);
const chats = [];
for (const fn of chatFiles) {
  if (!fn.endsWith('.json')) continue;
  const rec = safeReadJson(path.join(CHATIN_DIR, fn));
  if (!rec || !rec.captured_at) continue;
  if (new Date(rec.captured_at).getTime() < since) continue;
  chats.push(rec);
}
chats.sort((a, b) => a.captured_at.localeCompare(b.captured_at));

const totalVoices = feedback.length + chats.length;

if (totalVoices === 0) {
  // Nothing to digest. Send a quiet ping so Governor knows the system ran.
  const quietMessage = 'Morning digest: zero family voices in the last 24h. System healthy. Have a good day.';
  try {
    await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
      method: 'POST',
      headers: { 'Title': 'PoeTech daily digest - quiet morning', 'Priority': '2', 'Tags': 'sunrise', 'Content-Type': 'text/plain' },
      body: quietMessage,
      signal: AbortSignal.timeout(5000)
    });
  } catch (_) {}
  return [{ json: { ok: true, message: quietMessage, voice_count: 0 } }];
}

// Build the Ollama prompt for summarization.
const voicesText = [
  feedback.length ? '## Suggest button submissions (' + feedback.length + ')' : '',
  ...feedback.map(f => '- [' + f.sender + ' / ' + f.type + (f.screen_context && f.screen_context.path ? ' on ' + f.screen_context.path : '') + '] ' + f.message),
  chats.length ? '\n## Chat thoughts (' + chats.length + ')' : '',
  ...chats.map(c => '- [' + c.sender + '] ' + (c.text || c.raw_text || '').slice(0, 400))
].filter(Boolean).join('\n');

const prompt = `You are the morning digest generator for the PoeTech Family OS Foundation Agent.

The team needs a 5-7 sentence summary of the family voices captured in the last 24 hours. Group by sender. Name actionable items. Note any patterns.

Direct tone, warm but not flowery. No emoji. No filler. Speak as the Foundation Agent.

Respect these family conventions:
- Refer to the family members by their handles (dpoe = Darrell, cpoe = Christina, christiana = Christiana).
- Distinguish 'feedback' (Suggest button) from 'thought' (@nas chat).
- Identify items that look like they need code work versus items that are conversational.

Family voices to summarize:

${voicesText}

Return ONLY the summary text. No preamble, no markdown header.`;

let summary = '';
try {
  const ollamaResp = await fetch(OLLAMA_BASE + '/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: OLLAMA_MODEL, prompt: prompt, stream: false, options: { temperature: 0.4, num_predict: 600 } }),
    signal: AbortSignal.timeout(120000)
  });
  const data = await ollamaResp.json();
  summary = (data.response || '').trim();
} catch (e) {
  summary = 'Ollama summarization failed: ' + String(e) + '. Raw voice count: ' + totalVoices + '. Review the feedback and chatin directories directly.';
}

const title = 'PoeTech daily digest - ' + totalVoices + ' voice' + (totalVoices === 1 ? '' : 's');

try {
  await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
    method: 'POST',
    headers: { 'Title': title, 'Priority': '4', 'Tags': 'sunrise', 'Content-Type': 'text/plain' },
    body: summary,
    signal: AbortSignal.timeout(5000)
  });
} catch (_) {}

return [{ json: { ok: true, voice_count: totalVoices, feedback_count: feedback.length, chat_count: chats.length, summary } }];
